effect.shader:
void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    float rad = radians(angle);
    vec2 axis = vec2(cos(rad), sin(rad));
    vec2 centred = (acScreenNorm - 0.5) * vec2(acAspect, 1.0);

    // O alcance do retângulo naquela direção. Sem normalizar por ele, a mesma
    // porcentagem revelaria mais na diagonal que na horizontal — e a cortina
    // pareceria acelerar sozinha ao girar o ângulo.
    float support = max(0.5 * (acAspect * abs(axis.x) + abs(axis.y)), 0.0001);
    float position = (dot(centred, axis) + support) / (2.0 * support);

    float cut = completion * 0.01;
    float soft = max(feather, 0.0005);
    float mask = smoothstep(cut - soft, cut + soft, position);

    if (invertWipe) mask = 1.0 - mask;

    fragColor = vec4(color.rgb, color.a * mask);
}
